workflow-item.script:
var logPrefix = "[CB][Benchmark ES5 vs Node] ";

if (!payloadSizeBytes || payloadSizeBytes < 1 || payloadSizeBytes > 1048576) {
    throw logPrefix + "payloadSizeBytes must be between 1 and 1048576";
}
if (!es5Repetitions || es5Repetitions < 1 || es5Repetitions > 100) {
    throw logPrefix + "es5Repetitions must be between 1 and 100";
}
if (includeNode === true && (!nodeRepetitions || nodeRepetitions < 1 || nodeRepetitions > 20)) {
    throw logPrefix + "nodeRepetitions must be between 1 and 20";
}

// Same payload as the action measureCryptoTimings builds
var size = Math.floor(payloadSizeBytes);
var chunk = "abcdefghijklmnopqrstuvwxyz0123456789";
var parts = [];
var length = 0;
while (length < size) {
    parts.push(chunk);
    length += chunk.length;
}
payloadText = parts.join("").substring(0, size);

var CryptoUtils = System.getModule("in.co.cloudblogger.crypto").CryptoUtils();
var crypto = new CryptoUtils();
aesKeyHex = crypto.bytesToHex(crypto.randomBytes(32));
hmacKey = "cb-benchmark-" + System.nextUUID();
algorithm = "SHA-256";
hexFormat = "hex";
textFormat = "text";
warmText = "warm-up";
repIndex = 0;
nodeTimings = new Properties();

System.log(logPrefix + "Payload " + size + " bytes, ES5 runs: " + es5Repetitions +
    (includeNode === true ? ", Node.js runs: " + nodeRepetitions : ", Node.js skipped"));

firstCallMs = new Date().getTime() - stepStart;
System.log("[CB][Benchmark ES5 vs Node] Node.js first call: " + firstCallMs + " ms");
stepStart = new Date().getTime();

var elapsed = new Date().getTime() - stepStart;
var list = nodeTimings.get("sha256") ? JSON.parse(nodeTimings.get("sha256")) : [];
list.push(elapsed);
nodeTimings.put("sha256", JSON.stringify(list));
stepStart = new Date().getTime();

var elapsed = new Date().getTime() - stepStart;
var list = nodeTimings.get("hmac") ? JSON.parse(nodeTimings.get("hmac")) : [];
list.push(elapsed);
nodeTimings.put("hmac", JSON.stringify(list));
stepStart = new Date().getTime();

var elapsed = new Date().getTime() - stepStart;
var list = nodeTimings.get("aesEncrypt") ? JSON.parse(nodeTimings.get("aesEncrypt")) : [];
list.push(elapsed);
nodeTimings.put("aesEncrypt", JSON.stringify(list));
stepStart = new Date().getTime();

var elapsed = new Date().getTime() - stepStart;
var list = nodeTimings.get("aesDecrypt") ? JSON.parse(nodeTimings.get("aesDecrypt")) : [];
list.push(elapsed);
nodeTimings.put("aesDecrypt", JSON.stringify(list));
stepStart = new Date().getTime();
if (aesPlain !== payloadText) {
    throw "[CB][Benchmark ES5 vs Node] Node.js AES round trip returned different text";
}
repIndex = repIndex + 1;

var names = ["sha256", "hmac", "aesEncrypt", "aesDecrypt"];
nodeResults = new Properties();
for (var n = 0; n < names.length; n++) {
    var list = JSON.parse(nodeTimings.get(names[n]));
    list.sort(function (a, b) { return a - b; });
    nodeResults.put(names[n] + ".medianMs", list[Math.floor(list.length / 2)]);
    nodeResults.put(names[n] + ".minMs", list[0]);
    nodeResults.put(names[n] + ".maxMs", list[list.length - 1]);
}
nodeResults.put("firstCallMs", firstCallMs);
nodeResults.put("sha256.digest", sha256Digest);
nodeResults.put("hmac.digest", hmacDigest);
System.log("[CB][Benchmark ES5 vs Node] Node.js done: SHA-256 " + nodeResults.get("sha256.medianMs") + " ms, AES encrypt " + nodeResults.get("aesEncrypt.medianMs") + " ms (medians of " + nodeRepetitions + ")");

var logPrefix = "[CB][Benchmark ES5 vs Node] ";

function pad(text, width) {
    var s = String(text);
    while (s.length < width) {
        s += " ";
    }
    return s;
}

function formatMs(ms) {
    if (ms === null || ms === undefined) {
        return "-";
    }
    return ms >= 1000 ? (Math.round(ms / 100) / 10) + " s" : ms + " ms";
}

var hasNode = includeNode === true && nodeResults !== null && nodeResults !== undefined;
var rows = [
    { key: "sha256", label: "SHA-256" },
    { key: "hmac", label: "HMAC-SHA256" },
    { key: "aesEncrypt", label: "AES encrypt" },
    { key: "aesDecrypt", label: "AES decrypt" }
];

results = new Properties();
results.put("payloadSizeBytes", Math.floor(payloadSizeBytes));

var lines = [];
lines.push("Crypto benchmark, payload " + Math.floor(payloadSizeBytes) + " bytes (median times)");
lines.push(pad("Operation", 14) + pad("ES5", 12) + (hasNode ? "Node.js" : ""));
lines.push(pad("---------", 14) + pad("---", 12) + (hasNode ? "-------" : ""));

var fields = ["medianMs", "minMs", "maxMs"];
for (var r = 0; r < rows.length; r++) {
    var es5Median = es5Results.get(rows[r].key + ".medianMs");
    var nodeMedian = hasNode ? nodeResults.get(rows[r].key + ".medianMs") : null;
    lines.push(pad(rows[r].label, 14) + pad(formatMs(es5Median), 12) + (hasNode ? formatMs(nodeMedian) : ""));
    for (var f = 0; f < fields.length; f++) {
        results.put("es5." + rows[r].key + "." + fields[f], es5Results.get(rows[r].key + "." + fields[f]));
        if (hasNode) {
            results.put("node." + rows[r].key + "." + fields[f], nodeResults.get(rows[r].key + "." + fields[f]));
        }
    }
}

if (hasNode) {
    var digestsMatch = es5Results.get("sha256.digest") === nodeResults.get("sha256.digest") &&
        es5Results.get("hmac.digest") === nodeResults.get("hmac.digest");
    results.put("node.firstCallMs", nodeResults.get("firstCallMs"));
    results.put("digestsMatch", digestsMatch);
    lines.push("");
    lines.push("Node.js first call (may include cold start): " + formatMs(nodeResults.get("firstCallMs")));
    lines.push("ES5 and Node.js SHA-256/HMAC outputs match: " + (digestsMatch ? "yes" : "NO"));
    lines.push("AES: ES5 uses CBC (lab/test only), Node.js uses GCM");
    if (!digestsMatch) {
        System.warn(logPrefix + "ES5 and Node.js digests differ");
    }
}

summary = lines.join("\n");
for (var l = 0; l < lines.length; l++) {
    System.log(logPrefix + lines[l]);
}
